package com.android.tools.lint.checks;

import static com.android.SdkConstants.AUTO_URI;
import static com.android.SdkConstants.TOOLS_URI;

import com.android.annotations.NonNull;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.LayoutDetector;
import com.android.tools.lint.detector.api.Project;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;

import org.w3c.dom.Attr;
import org.w3c.dom.Element;

import java.util.Collection;
import java.util.Collections;

public class NamespaceDetector extends LayoutDetector {
    private static final String PREFIX = "http://schemas.android.com/apk/res/";

    public static final Issue ISSUE = Issue.create(
            "LibraryCustomView",
            "Custom views in libraries should use res-auto-namespace",
            "When using a custom view with custom attributes in a library project, " +
            "the layout must use the special namespace `http://schemas.android.com/apk/res-auto` " +
            "instead of a URI which includes the library project's own package.",
            Category.CORRECTNESS,
            6,
            Severity.FATAL,
            new Implementation(NamespaceDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    @Override
    public boolean appliesTo(ResourceFolderType folderType) {
        return folderType == ResourceFolderType.LAYOUT;
    }

    @Override
    public Collection<String> getApplicableAttributes() {
        return XmlScannerConstants.ATTR_ALL;
    }

    @Override
    public void visitAttribute(@NonNull XmlContext context, @NonNull Attr attribute) {
        String uri = attribute.getNamespaceURI();
        if (uri == null || uri.isEmpty() || !uri.startsWith(PREFIX)) {
            return;
        }

        Project project = context.getProject();
        if (!project.isLibrary()) {
            return;
        }

        String pkg = project.getPackage();
        if (pkg == null) {
            return;
        }

        String expected = PREFIX + pkg;
        if (uri.equals(expected)) {
            String auto = AUTO_URI;
            String name = attribute.getLocalName();
            String prefix = attribute.getPrefix();
            String message;
            if (prefix != null) {
                message = String.format(
                        "When using a custom view in a library, you must use the " +
                        "`%2$s` namespace, not the `%1$s` namespace. " +
                        "Change `xmlns:%3$s=\"%1$s\"` to `xmlns:%3$s=\"%2$s`.",
                        expected, auto, prefix);
            } else {
                message = String.format(
                        "When using a custom view in a library, you must use the " +
                        "`%2$s` namespace, not the `%1$s` namespace.",
                        expected, auto);
            }
            context.report(ISSUE, attribute, context.getValueLocation(attribute), message);
        }
    }
}
